"""AQS-END-002 end-of-life material return (X-END-02, A-M-191). Every plant BOM line (AQS-INV-006 PLANT_BOM.csv, unit BOMs included) is
assigned a plant feed class of AQS-ASSAY-001 (FEED_ASSAY.md section 1) from its material text, or its item text where the material is blank,
with the plant entry point and any hold. A line whose class has no route in the present plant is held with its reason. Writes
docs-authority/inventory/EOL_RETURN.csv. Run: python3 docs-authority/_eol.py"""
import csv, collections, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R)
RULES = [  # (keywords, class, entry, hold or None) first match wins
 (('ndfeb', 'rare earth'), 'metal_reactive', 'leach to precipitate cake (rare earths are not electrowon)', 'Nd/Dy recovery has no unit: held in cake'),
 (('pt-rh', 'platinum'), 'metal_plateable', 'held', 'Pt-Rh is not in the plateable set and has no recovery unit: gauze kept and re-drawn in house'),
 (('titanium', 'ti grade'), 'metal_reactive', 'precipitate cake', 'Ti is not leached at the plant acid strength: held, re-used as cathode blanks'),
 (('6063', 'aluminium', 'aluminum', 'die-cast al', 'al cage', 'a356'), 'metal_reactive', 'leach to precipitate cake', None),
 (('pvdf', 'ptfe', 'fluoro', 'fkm'), 'organic', 'held', 'fluoropolymer: pyrolysis releases HF, which the HCl scrubbers are not designed for'),
 (('pvc', 'cpvc'), 'organic', 'OIL_DRYER, OIL_PYRO; chlorine to the HCl loop', None),
 (('frp', 'vinyl ester'), 'organic', 'OIL_PYRO; the glass fibre then reports to silicate_oxide (FLOAT_SINK)', None),
 (('hdpe', 'pe100', 'pe4710', 'pp-h', 'polyprop', 'pir', 'epdm', 'silicone', 'rubber', 'nylon', 'pps', 'peek', 'resin', 'membrane', 'gasket', 'pcb'), 'organic', 'OIL_DRYER, OIL_PYRO', None),
 (('graphite', 'carbon felt'), 'organic', 'OIL_PYRO (char)', None),
 (('glass', 'mineral wool', 'mica', 'refractory', 'ceramic', 'concrete', 'alumina', 'zeolite', '13x', 'silica'), 'silicate_oxide', 'FLOAT_SINK, glass line, or IA-SINK-01', None),
 (('316', '304', 'stainless', 'sa-182', 'sa-240', 'a312', 'a106', 'carbon steel', 'steel', 'c45', 'lamination', 'm270', 'm400', 'iron', 'cs ', 'nickel', 'incoloy', 'inconel', 'nicr', '310s', '430f', 'sa-105', 'sa-106', 'fastener', 'stud', 'compressor shell', 'frame', 'flange'), 'metal_plateable', 'LEACH_CSTR_1, EW_1..9 (Fe, Ni); Cr and Mo report to the cake', None),
 (('cu', 'copper', 'magnet wire', 'bronze', 'brass', 'busbar', 'cable'), 'metal_plateable', 'LEACH_CSTR_1, EW (Cu, Sn, Zn)', None),
 (('electronics', 'connector', 'terminal box', 'plc', 'driver'), 'metal_plateable', 'WEEE route: OIL_PYRO strips the board polymer, then LEACH_CSTR_1 and EW (Cu, Sn, Ag, Au)', None),
 (('bearing',), 'metal_plateable', 'LEACH_CSTR_1, EW (52100 steel)', None),
 (('no wetted alloy', 'water'), 'unassigned', 'by part', 'material not stated on the line'),
]
def cls(material, item):
    t = (material or item).lower() + ' ' + (item or '').lower()
    for kw, c, e, h in RULES:
        if any(k in t for k in kw): return c, e, h
    return 'unassigned', '-', 'material not identified'
rows = []
for r in csv.DictReader(open('docs-authority/inventory/PLANT_BOM.csv')):
    c, e, h = cls(r['material'], r['item']); rows.append(dict(r, feed_class=c, entry=e, hold=h or ''))
with open('docs-authority/inventory/EOL_RETURN.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)
C = collections.Counter(r['feed_class'] for r in rows); H = collections.Counter(r['hold'] for r in rows if r['hold'])
U = collections.defaultdict(collections.Counter)
for r in rows: U[r['unit']][r['feed_class']] += 1
md = ['# End-of-life material return', '', 'Document number: AQS-END-002', 'Revision: A', 'Date: 2026-10-16',
      'Authority: AQS-PLAN-007 X-END-02. Generated by `docs-authority/_eol.py`; line-by-line in `docs-authority/inventory/EOL_RETURN.csv`. Classes are the seven of AQS-ASSAY-001 section 1. Study. A-M-191.', '',
      'At end of life each part goes back into the plant as feed of its class, through the same dock and assay as any other lot. Classing is by BOM line (count), not mass; the mass split waits for unit weights.', '',
      '| Feed class | BOM lines | Share |', '|---|---|---|'] + [f'| {k} | {v} | {v/len(rows)*100:.0f} % |' for k, v in C.most_common()]
md += ['', '## Held lines (no route in the present plant)', '', '| Reason | Lines |', '|---|---|'] + [f'| {k} | {v} |' for k, v in H.most_common()]
md += ['', 'Findings: fluoropolymer parts (PVDF piping, pumps and seals) cannot go to OIL_PYRO because the HF is outside the scrubber design basis; options are mechanical re-use as regrind for non-pressure parts, or an HF-rated scrubber stage. NdFeB magnets sit in the precipitate cake with no recovery unit; the ferrite motor variant (AQS-INV-005) removes this hold. Titanium cathode blanks are re-used directly.', '',
       '## Per unit (lines by class)', '', '| Unit | ' + ' | '.join(c for c, _ in C.most_common()) + ' |', '|---|' + '---|'*len(C)]
md += [f"| {u} | " + ' | '.join(str(U[u].get(c, 0)) for c, _ in C.most_common()) + ' |' for u in sorted(U)]
open('docs-authority/EOL_RETURN.md', 'w').write('\n'.join(md) + '\n'); print(dict(C)); print(dict(H))
